from typing import List

class Solution:
    def tripletCount(self, a: List[int], b: List[int], c: List[int]) -> int:
        def parity_counts(arr):
            cnt = [0, 0]
            for x in arr:
                cnt[bin(x).count("1") & 1] += 1
            return cnt

        ca, cb, cc = parity_counts(a), parity_counts(b), parity_counts(c)

        total = 0
        for pa in range(2):
            for pb in range(2):
                pc = pa ^ pb  # needed parity of c so the three parities sum to even
                total += ca[pa] * cb[pb] * cc[pc]
        return total
